import { AxisScale } from '@visx/axis';
import React from 'react';

import { DivAxisWrapper } from './DivAxisWrapper.js';
import { Formatter } from '../../../types/formatter.js';
import { AxisBottom } from '../AxisBottom.js';
import { axisFontProps } from '../constants.js';
import { bottomTickLabelDateProps } from '../functions/get-tick-label-props.js';

/**
 * @internal
 */
export interface TimeBottomAxisProps {
  scale: AxisScale;
  containerWidth: number;
  containerHeight: number;
  formatter?: Formatter;
  label?: string;
  stroke?: string;
  ticks: string[];
  formattedTicks: string[];
}

const TICK_LABEL_PROPS = bottomTickLabelDateProps;

/**
 * @internal
 */
export const TimeBottomAxis = (props: TimeBottomAxisProps) => {
  const {
    scale,
    containerWidth,
    containerHeight,
    label,
    stroke,
    ticks,
    formattedTicks,
  } = props;

  const tickFormat = (_: unknown, index: number) => formattedTicks[index];

  return (
    <DivAxisWrapper
      divAxisStyle={axisFontProps}
      ticks={formattedTicks}
      label={label}
      isTickVertical
    >
      <AxisBottom
        data-testid="time-axis-bottom"
        scale={scale}
        containerSize={containerWidth}
        height={containerHeight}
        tickValues={ticks}
        tickLabelProps={TICK_LABEL_PROPS}
        tickFormat={tickFormat}
        label={label}
        stroke={stroke}
      />
    </DivAxisWrapper>
  );
};

TimeBottomAxis['displayName'] = 'TimeBottomAxis';
